1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.security.AuthMode;
4	import com.maritime.platform.gateway.security.GatewayPrincipal;
5	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
6	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
7	import com.maritime.platform.gateway.security.hmac.HmacAuthenticationManager;
8	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
9	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
10	
11	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
12	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
13	import org.springframework.cloud.gateway.filter.GlobalFilter;
14	import org.springframework.core.Ordered;
15	import org.springframework.core.annotation.Order;
16	import org.springframework.core.io.buffer.DataBuffer;
17	import org.springframework.core.io.buffer.DataBufferUtils;
18	import org.springframework.http.HttpStatus;
19	import org.springframework.http.MediaType;
20	import org.springframework.http.server.reactive.ServerHttpRequest;
21	import org.springframework.http.server.reactive.ServerHttpRequestDecorator;
22	import org.springframework.stereotype.Component;
23	import org.springframework.web.server.ServerWebExchange;
24	
25	import reactor.core.publisher.Flux;
26	import reactor.core.publisher.Mono;
27	
28	import java.nio.charset.StandardCharsets;
29	
30	/**
31	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
32	 * <p>
33	 * Reads the request body once to compute the SHA-256 digest, then caches it
34	 * in a decorated exchange so downstream filters and handlers can still read it.
35	 * Stores the mapped {@link GatewayPrincipal.App} in the exchange.
36	 */
37	@Component
38	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
39	@Order(GatewayFilterOrder.HMAC_AUTHENTICATION)
40	public class HmacAuthenticationGatewayFilter implements GlobalFilter, Ordered {
41	
42		private final HmacAuthenticationManager authManager;
43		private final GatewaySecurityProperties properties;
44	
45		public HmacAuthenticationGatewayFilter(HmacAuthenticationManager authManager,
46				GatewaySecurityProperties properties) {
47			this.authManager = authManager;
48			this.properties = properties;
49		}
50	
51		@Override
52		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
53			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
54			if (!requiresHmac(policy)) {
55				return chain.filter(exchange);
56			}
57	
58			GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
59			String appKey = exchange.getRequest().getHeaders().getFirst(hdrs.getAppKey());
60			String timestamp = exchange.getRequest().getHeaders().getFirst(hdrs.getTimestamp());
61			String nonce = exchange.getRequest().getHeaders().getFirst(hdrs.getNonce());
62			String bodyDigest = exchange.getRequest().getHeaders().getFirst(hdrs.getBodyDigest());
63			String signature = exchange.getRequest().getHeaders().getFirst(hdrs.getSignature());
64	
65			if (isAnyBlank(appKey, timestamp, nonce, bodyDigest, signature)) {
66				return writeError(exchange, GatewayAuthErrorCode.MISSING_HMAC_HEADERS,
67						"Missing one or more HMAC headers: " +
68								hdrs.getAppKey() + ", " + hdrs.getTimestamp() + ", " +
69								hdrs.getNonce() + ", " + hdrs.getBodyDigest() + ", " +
70								hdrs.getSignature());
71			}
72	
73			return readAndCacheBody(exchange)
74					.flatMap(cachedExchange -> {
75						byte[] bodyBytes = cachedExchange.getAttribute("gateway.cachedBody");
76						String method = exchange.getRequest().getMethod().name();
77						String rawPath = exchange.getRequest().getURI().getRawPath();
78						String rawQuery = exchange.getRequest().getURI().getRawQuery();
79	
80						return authManager.authenticate(appKey, timestamp, nonce, bodyDigest, signature,
81										method, rawPath, rawQuery, bodyBytes != null ? bodyBytes : new byte[0])
82								.flatMap(principal -> {
83									cachedExchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
84									return chain.filter(cachedExchange);
85								})
86								.onErrorResume(JwtAuthenticationException.class,
87										e -> writeError(cachedExchange, e.getErrorCode(), e.getMessage()));
88					});
89		}
90	
91		@Override
92		public int getOrder() {
93			return GatewayFilterOrder.HMAC_AUTHENTICATION;
94		}
95	
96		/**
97		 * Reads the request body once, caches the bytes, and returns a decorated exchange
98		 * whose request body can be re-read by downstream filters and handlers.
99		 */
100		private Mono<ServerWebExchange> readAndCacheBody(ServerWebExchange exchange) {
101			return DataBufferUtils.join(exchange.getRequest().getBody())
102					.map(buf -> {
103						byte[] bytes = new byte[buf.readableByteCount()];
104						buf.read(bytes);
105						DataBufferUtils.release(buf);
106						return bytes;
107					})
108					.switchIfEmpty(Mono.just(new byte[0]))
109					.map(bytes -> {
110						ServerHttpRequest decorated = new ServerHttpRequestDecorator(exchange.getRequest()) {
111							@Override
112							public Flux<DataBuffer> getBody() {
113								return Flux.just(
114										exchange.getResponse().bufferFactory().wrap(bytes));
115							}
116						};
117						ServerWebExchange cached = exchange.mutate().request(decorated).build();
118						cached.getAttributes().put("gateway.cachedBody", bytes);
119						return cached;
120					});
121		}
122	
123		private boolean requiresHmac(RouteSecurityPolicy policy) {
124			if (policy == null) {
125				return false;
126			}
127			AuthMode mode = policy.getAuthMode();
128			return mode == AuthMode.HMAC || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
129		}
130	
131		private boolean isAnyBlank(String... values) {
132			for (String v : values) {
133				if (v == null || v.isBlank()) {
134					return true;
135				}
136			}
137			return false;
138		}
139	
140		private Mono<Void> writeError(ServerWebExchange exchange, String code, String message) {
141			exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
142			exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
143			String body = String.format("{\"code\":\"%s\",\"message\":\"%s\"}",
144					escapeJson(code), escapeJson(message));
145			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
146			return exchange.getResponse()
147					.writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(bytes)));
148		}
149	
150		private static String escapeJson(String s) {
151			if (s == null) {
152				return "";
153			}
154			return s.replace("\\", "\\\\")
155					.replace("\"", "\\\"")
156					.replace("\n", "\\n")
157					.replace("\r", "\\r")
158					.replace("\t", "\\t");
159		}
160	}
161

1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.security.AuthMode;
4	import com.maritime.platform.gateway.security.GatewayPrincipal;
5	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
6	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
7	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
8	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationManager;
9	
10	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
11	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
12	import org.springframework.cloud.gateway.filter.GlobalFilter;
13	import org.springframework.core.Ordered;
14	import org.springframework.core.annotation.Order;
15	import org.springframework.http.HttpStatus;
16	import org.springframework.http.MediaType;
17	import org.springframework.stereotype.Component;
18	import org.springframework.web.server.ServerWebExchange;
19	
20	import reactor.core.publisher.Mono;
21	
22	import java.nio.charset.StandardCharsets;
23	
24	/**
25	 * Extracts and validates a JWT Bearer token for routes that require
26	 * JWT authentication. Stores the mapped {@link GatewayPrincipal.User}
27	 * in the exchange for downstream filters and handlers.
28	 */
29	@Component
30	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
31	@Order(GatewayFilterOrder.JWT_AUTHENTICATION)
32	public class JwtAuthenticationGatewayFilter implements GlobalFilter, Ordered {
33	
34		private final JwtAuthenticationManager authManager;
35	
36		public JwtAuthenticationGatewayFilter(JwtAuthenticationManager authManager) {
37			this.authManager = authManager;
38		}
39	
40		@Override
41		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
42			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
43			if (!requiresJwt(policy)) {
44				return chain.filter(exchange);
45			}
46	
47			String token = extractBearerToken(exchange);
48			if (token == null || token.isEmpty()) {
49				return writeError(exchange, GatewayAuthErrorCode.MISSING_TOKEN,
50						"Authorization header is missing or does not contain a Bearer token");
51			}
52	
53			return authManager.authenticate(token)
54					.flatMap(principal -> {
55						exchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
56						return chain.filter(exchange);
57					})
58					.onErrorResume(JwtAuthenticationException.class,
59							e -> writeError(exchange, e.getErrorCode(), e.getMessage()));
60		}
61	
62		@Override
63		public int getOrder() {
64			return GatewayFilterOrder.JWT_AUTHENTICATION;
65		}
66	
67		private boolean requiresJwt(RouteSecurityPolicy policy) {
68			if (policy == null) {
69				return false;
70			}
71			AuthMode mode = policy.getAuthMode();
72			return mode == AuthMode.JWT || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
73		}
74	
75		private String extractBearerToken(ServerWebExchange exchange) {
76			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
77			if (auth != null && auth.startsWith("Bearer ")) {
78				return auth.substring(7).trim();
79			}
80			return null;
81		}
