25	/**
26	 * Enforces JWT nonce validation for write requests on JWT-protected routes.
27	 * <p>
28	 * Runs after {@link JwtAuthenticationGatewayFilter} so the authenticated
29	 * principal is available. Only enforces nonce for HTTP methods configured
30	 * in {@code maritime.gateway.security.jwt.nonce.required-methods}
31	 * (default: POST, PUT, PATCH, DELETE).
32	 */
33	@Component
34	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
35	@Order(GatewayFilterOrder.JWT_NONCE)
36	public class JwtNonceGatewayFilter implements GlobalFilter, Ordered {
37	
38		private final JwtNonceValidator nonceValidator;
39		private final GatewaySecurityProperties properties;
40	
41		public JwtNonceGatewayFilter(JwtNonceValidator nonceValidator,
42				GatewaySecurityProperties properties) {
43			this.nonceValidator = nonceValidator;
44			this.properties = properties;
45		}
46	
47		@Override
48		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
49			if (!properties.getJwt().getNonce().isEnabled()) {
50				return chain.filter(exchange);
51			}
52	
53			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
54			if (!requiresJwt(policy)) {
55				return chain.filter(exchange);
56			}
57	
58			String method = exchange.getRequest().getMethod().name();
59			if (!properties.getJwt().getNonce().getRequiredMethods().contains(method)) {
60				return chain.filter(exchange);
61			}
62	
63			GatewayPrincipal.User principal = exchange.getAttribute(GatewayPrincipal.ATTRIBUTE);
64			if (principal == null) {
65				return chain.filter(exchange);
66			}
67	
68			String nonce = exchange.getRequest().getHeaders().getFirst("X-Nonce");
69			if (nonce == null || nonce.isEmpty()) {
70				return writeError(exchange, GatewayAuthErrorCode.NONCE_REQUIRED,
71						"X-Nonce header is required for " + method + " requests");
72			}
73	
74			return nonceValidator.validate(principal.sessionId(), nonce)
75					.then(chain.filter(exchange))
76					.onErrorResume(JwtAuthenticationException.class,
77							e -> writeError(exchange, e.getErrorCode(), e.getMessage()));
78		}
79	
80		@Override
81		public int getOrder() {
82			return GatewayFilterOrder.JWT_NONCE;
83		}
84	
85		private boolean requiresJwt(RouteSecurityPolicy policy) {
86			if (policy == null) {
87				return false;
88			}
89			AuthMode mode = policy.getAuthMode();
90			return mode == AuthMode.JWT || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
91		}
92	
93		private Mono<Void> writeError(ServerWebExchange exchange, String code, String message) {
94			exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
95			exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
96			String body = String.format("{\"code\":\"%s\",\"message\":\"%s\"}",
97					escapeJson(code), escapeJson(message));
98			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
99			return exchange.getResponse()
100					.writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(bytes)));
101		}
102	
103		private static String escapeJson(String s) {
104			if (s == null) {
105				return "";
106			}
107			return s.replace("\\", "\\\\")
108					.replace("\"", "\\\"")
109					.replace("\n", "\\n")
110					.replace("\r", "\\r")
111					.replace("\t", "\\t");
112		}
113	}
