27		private static void addRoute(GatewaySecurityProperties props, String id,
28		                             List<String> paths, List<String> methods, AuthMode mode) {
29			GatewaySecurityProperties.RoutePolicy rp = new GatewaySecurityProperties.RoutePolicy();
30			rp.setId(id);
31			rp.setPaths(paths);
32			if (methods != null) {
33				rp.setMethods(methods);
34			}
35			rp.setAuthMode(mode);
36			props.getRoutes().add(rp);
