20	@DisplayName("JwtStateValidator tests")
21	@ExtendWith(MockitoExtension.class)
22	class JwtStateValidatorTest {
23	
24	    @Mock
25	    private ReactiveRedisOperations<String, String> redisOps;
26	
27	    @Mock
28	    private ReactiveValueOperations<String, String> valueOps;
29	
30	    private GatewaySecurityProperties properties;
31	
32	    @BeforeEach
33	    void setUp() {
34	        properties = new GatewaySecurityProperties();
35	        properties.getJwt().setEnabled(true);
36	        properties.getJwt().setSecret("my-test-secret-key-minimum-256-bits-long!!");
37	        properties.getJwt().setIssuer("maritime-platform");
38	        lenient().when(redisOps.opsForValue()).thenReturn(valueOps);
39	    }
40	
41	    private JwtStateValidator validator() {
42	        return new JwtStateValidator(redisOps, properties);
43	    }
44	
45	    /** Disable all but session check for isolated testing. */
46	    private void isolateSessionCheck() {
47	        properties.getJwt().getValidation().setCheckBlacklist(false);
48	        properties.getJwt().getValidation().setCheckUserEnabled(false);
49	    }
50	
51	    /** Disable user-enabled check for blacklist-focused testing. */
52	    private void isolateBlacklistCheck() {
53	        properties.getJwt().getValidation().setCheckUserEnabled(false);
54	    }
